<script>
const form=document.getElementById('price-change-form'),cat=document.getElementById('category_id'),sub=document.getElementById('subcategory_id'),prod=document.getElementById('product_id'),vars=document.getElementById('variant_ids'),previewBtn=document.getElementById('preview-btn'),submitBtn=document.getElementById('submit-btn'),body=document.getElementById('preview-body'),msg=document.getElementById('preview-message');let previewIsValid=false,counts={variants_count:0},variantItems=[],selectedVariantIds=new Set();const csrf='{{ csrf_token() }}',variantPicker=document.getElementById('variantPicker'),variantPickerButton=document.getElementById('variantPickerButton'),variantPickerPanel=document.getElementById('variantPickerPanel'),variantPickerButtonText=document.getElementById('variantPickerButtonText'),variantSearchInput=document.getElementById('variantSearchInput'),variantPickerList=document.getElementById('variantPickerList'),variantSelectedTags=document.getElementById('variantSelectedTags'),productPicker=document.getElementById('productPicker'),productPickerButton=document.getElementById('productPickerButton'),productPickerPanel=document.getElementById('productPickerPanel'),productPickerButtonText=document.getElementById('productPickerButtonText'),productSearchInput=document.getElementById('productSearchInput'),productPickerList=document.getElementById('productPickerList'),productSearchStatus=document.getElementById('productSearchStatus');let productPage=1,productMore=false,productLoading=false,productRequest=null,productRequestSequence=0,productTimer=null;
function money(n){return Number(n||0).toLocaleString('fa-IR')} function escapeHtml(value){let el=document.createElement('span');el.textContent=String(value??'');return el.innerHTML} function opt(el,v,t){let o=document.createElement('option');o.value=v;o.textContent=t;el.appendChild(o);return o} function invalidate(text='محدوده یا نوع تغییر عوض شده است. پیش‌نمایش را مجدداً اجرا کنید.'){previewIsValid=false;submitBtn.disabled=true;body.innerHTML='';msg.textContent=text}
function scopePayload(){return new FormData(form)} function selectedVariantsData(){return variantItems.filter(v=>selectedVariantIds.has(String(v.id)))} function updateText(){let c=cat.selectedOptions[0]?.text||'',s=sub.value?sub.selectedOptions[0]?.text:'',p=prod.value?prod.selectedOptions[0]?.text:'',vc=selectedVariantIds.size;let txt='برای شروع، دسته‌بندی اصلی را انتخاب کنید.';if(cat.value&&!s&&!p)txt=`محدوده نهایی: تمام محصولات و تنوع‌های دسته‌بندی «${c}» و زیر‌دسته‌های آن`;if(s&&!p)txt=`محدوده نهایی: تمام محصولات و تنوع‌های زیر‌دسته «${s}»`;if(p&&!vc)txt=`محدوده نهایی: تمام تنوع‌های محصول «${p}»`;if(p&&vc)txt=`محدوده نهایی: ${vc} تنوع انتخاب‌شده از محصول «${p}»`;document.getElementById('scope-text').textContent=txt;document.getElementById('pre-preview-summary').textContent=cat.value&&document.getElementById('change_value').value?`${txt} | نوع تغییر: ${document.getElementById('change_type').selectedOptions[0].text} | مقدار: ${document.getElementById('change_value').value} ${document.getElementById('value-unit').textContent} | تعداد تنوع‌ها: ${counts.variants_count||0}`:'برای مشاهده پیش‌نمایش، دسته‌بندی، نوع تغییر و مقدار را تکمیل کنید.';previewBtn.disabled=!(cat.value&&document.getElementById('change_value').value&&(counts.variants_count||0)>0)}
function syncVariantSelect(){vars.innerHTML='';Array.from(new Set(selectedVariantIds)).forEach(id=>opt(vars,id,id).selected=true);vars.disabled=!prod.value} function setVariantPickerEnabled(enabled){variantPickerButton.disabled=!enabled;variantPickerButtonText.textContent=enabled?'همه تنوع‌های محصول':'ابتدا محصول را انتخاب کنید';if(!enabled)closeVariantPicker()} function resetVariantPicker(){selectedVariantIds=new Set();variantItems=[];variantSearchInput.value='';variantPickerList.innerHTML='';variantSelectedTags.innerHTML='';document.getElementById('availableVariantsCount').textContent='0';syncVariantSelect();setVariantPickerEnabled(false)}
function updateVariantButton(){let count=selectedVariantIds.size;variantPickerButtonText.textContent=!prod.value?'ابتدا محصول را انتخاب کنید':(count===0?'همه تنوع‌های محصول':(count===1?'1 تنوع انتخاب شده':count+' تنوع انتخاب شده'));document.getElementById('selectedVariantsCount').textContent=count;document.getElementById('availableVariantsCount').textContent=variantItems.length} function renderVariantTags(){variantSelectedTags.innerHTML='';let items=selectedVariantsData();items.slice(0,3).forEach(v=>{let tag=document.createElement('span');tag.className='picker-tag';tag.textContent=v.name||'تنوع';let b=document.createElement('button');b.type='button';b.textContent='×';b.addEventListener('click',()=>toggleVariant(String(v.id),false));tag.appendChild(b);variantSelectedTags.appendChild(tag)});if(items.length>3){let more=document.createElement('span');more.className='picker-tag';more.textContent='+ '+(items.length-3)+' مورد دیگر';variantSelectedTags.appendChild(more)}}
function filteredVariants(){let q=String(variantSearchInput.value||'').trim().toLowerCase();if(!q)return variantItems;return variantItems.filter(v=>[v.name,v.sku,v.code,v.model_name].some(x=>String(x||'').toLowerCase().includes(q)))} function renderVariantPicker(){variantPickerList.innerHTML='';let items=filteredVariants();if(!items.length){let e=document.createElement('div');e.className='muted-help p-2';e.textContent=variantItems.length?'نتیجه‌ای برای جستجو پیدا نشد.':'این محصول تنوع قابل انتخاب ندارد.';variantPickerList.appendChild(e)}items.forEach(v=>{let id=String(v.id),lbl=document.createElement('label');lbl.className='picker-item'+(selectedVariantIds.has(id)?' is-selected':'');lbl.setAttribute('role','option');lbl.setAttribute('aria-selected',selectedVariantIds.has(id)?'true':'false');let check=document.createElement('input');check.type='checkbox';check.value=id;check.checked=selectedVariantIds.has(id);check.addEventListener('change',()=>toggleVariant(id,check.checked));let wrap=document.createElement('div'),title=document.createElement('div'),small=document.createElement('small');title.textContent=v.name||'تنوع اصلی';small.textContent=`SKU: ${v.sku||v.code||'—'} | قیمت فعلی: ${money(v.sell_price)} ریال${v.is_active?'':' | غیرفعال'}`;wrap.appendChild(title);wrap.appendChild(small);lbl.appendChild(check);lbl.appendChild(wrap);variantPickerList.appendChild(lbl)});updateVariantButton();renderVariantTags()} function toggleVariant(id,checked){checked?selectedVariantIds.add(id):selectedVariantIds.delete(id);syncVariantSelect();renderVariantPicker();invalidate('محدوده تغییر کرده است. پیش‌نمایش را مجدداً اجرا کنید.');refreshCounts()}
function openVariantPicker(){if(variantPickerButton.disabled)return;variantPickerPanel.classList.add('open');variantPickerButton.setAttribute('aria-expanded','true');variantSearchInput.focus()} function closeVariantPicker(){variantPickerPanel.classList.remove('open');variantPickerButton.setAttribute('aria-expanded','false')} variantPickerButton.addEventListener('click',()=>variantPickerPanel.classList.contains('open')?closeVariantPicker():openVariantPicker());document.getElementById('closeVariantPicker').addEventListener('click',closeVariantPicker);document.addEventListener('click',e=>{if(!variantPicker.contains(e.target))closeVariantPicker()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeVariantPicker()});variantSearchInput.addEventListener('input',renderVariantPicker);document.getElementById('selectAllVariants').addEventListener('click',()=>{filteredVariants().forEach(v=>selectedVariantIds.add(String(v.id)));syncVariantSelect();renderVariantPicker();invalidate('محدوده تغییر کرده است. پیش‌نمایش را مجدداً اجرا کنید.');refreshCounts()});document.getElementById('clearVariants').addEventListener('click',()=>{selectedVariantIds=new Set();syncVariantSelect();renderVariantPicker();invalidate('محدوده تغییر کرده است. پیش‌نمایش را مجدداً اجرا کنید.');refreshCounts()});
async function refreshCounts(){updateText(); if(!cat.value)return;let res=await fetch('{{ route('products.price-changes.scope-summary') }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:scopePayload()});if(!res.ok){msg.textContent='خطا در محاسبه محدوده';return}counts=await res.json();document.getElementById('products-count').textContent=counts.products_count;document.getElementById('variants-count').textContent=counts.variants_count;document.getElementById('active-count').textContent=counts.active_variants_count;document.getElementById('invalid-count').textContent=counts.invalid_variants_count;if(!counts.variants_count)msg.textContent='هیچ تنوعی در این محدوده پیدا نشد.';updateText()}
function resetProductPicker(message='ابتدا زیر‌دسته‌بندی را انتخاب کنید'){productRequest?.abort();productRequest=null;productPage=1;productMore=false;productLoading=false;productSearchInput.value='';productPickerList.innerHTML='';prod.innerHTML='<option value="">همه محصولات این محدوده</option>';prod.disabled=true;productPickerButton.disabled=true;productPickerButtonText.textContent=message;productSearchStatus.textContent='برای نمایش کالاها فهرست را باز کنید.';document.getElementById('product-result-count').textContent='';productPickerPanel.classList.remove('open')}
function enableProductPicker(){prod.disabled=false;productPickerButton.disabled=false;productPickerButtonText.textContent='همه محصولات این زیر‌دسته';productSearchStatus.textContent='برای نمایش کالاها فهرست را باز کنید.'}
function renderProductResults(items,append){if(!append)productPickerList.innerHTML='';if(!items.length&&!append){let e=document.createElement('div');e.className='muted-help p-2';e.textContent='کالایی در این زیر‌دسته پیدا نشد';productPickerList.appendChild(e)}items.forEach(item=>{let button=document.createElement('button');button.type='button';button.className='picker-item product-result';let title=document.createElement('div'),small=document.createElement('small');title.textContent=item.name;small.textContent=[item.code&&`کد: ${item.code}`,item.sku&&`SKU: ${item.sku}`,`${item.available_variants_count} تنوع موجود`].filter(Boolean).join(' | ');button.append(title,small);button.addEventListener('click',()=>{prod.innerHTML='<option value="">همه محصولات این محدوده</option>';opt(prod,item.id,`${item.name}${item.code?' — '+item.code:''}`).selected=true;productPickerButtonText.textContent=`${item.name}${item.code?' — '+item.code:''}`;productPickerPanel.classList.remove('open');prod.dispatchEvent(new Event('change'))});productPickerList.appendChild(button)})}
async function searchProducts(reset=true){if(!cat.value||!sub.value||productLoading)return;if(reset){productPage=1;productMore=false}productLoading=true;productSearchStatus.textContent='در حال جست‌وجوی کالاها...';productRequest?.abort();productRequest=new AbortController();const sequence=++productRequestSequence;let url=new URL('{{ route('products.price-changes.products.search') }}',location.origin);url.searchParams.set('category_id',cat.value);url.searchParams.set('subcategory_id',sub.value);url.searchParams.set('q',productSearchInput.value.trim());url.searchParams.set('page',productPage);url.searchParams.set('per_page',20);form.querySelectorAll('input[type=checkbox]').forEach(el=>url.searchParams.set(el.name,el.checked?'1':'0'));try{let response=await fetch(url,{signal:productRequest.signal,headers:{'Accept':'application/json'}}),data=await response.json();if(sequence!==productRequestSequence)return;if(!response.ok)throw new Error();renderProductResults(data.results||[],!reset);productMore=!!data.pagination?.more;let total=Number(data.meta?.total||0);productSearchStatus.textContent=productMore?'برای نمایش موارد بیشتر به پایین پیمایش کنید.':'همه نتایج نمایش داده شد.';document.getElementById('product-result-count').textContent=`${total.toLocaleString('fa-IR')} کالا در این زیر‌دسته`;if(productMore)productPage++}catch(error){if(error.name!=='AbortError')productSearchStatus.textContent='دریافت لیست کالاها ناموفق بود؛ دوباره تلاش کنید.'}finally{if(sequence===productRequestSequence)productLoading=false}}
productPickerButton.addEventListener('click',()=>{let opening=!productPickerPanel.classList.contains('open');productPickerPanel.classList.toggle('open',opening);productPickerButton.setAttribute('aria-expanded',opening?'true':'false');if(opening){productSearchInput.focus();searchProducts(true)}});document.getElementById('closeProductPicker').addEventListener('click',()=>productPickerPanel.classList.remove('open'));productSearchInput.addEventListener('input',()=>{clearTimeout(productTimer);productTimer=setTimeout(()=>searchProducts(true),300)});productPickerList.addEventListener('scroll',()=>{if(productMore&&!productLoading&&productPickerList.scrollTop+productPickerList.clientHeight>=productPickerList.scrollHeight-40)searchProducts(false)});
cat.addEventListener('change',async()=>{invalidate();sub.innerHTML='<option value="">همه زیر‌دسته‌ها</option>';resetProductPicker();resetVariantPicker();sub.disabled=!cat.value;document.getElementById('subcategory-empty').classList.add('d-none');if(cat.value){let r=await fetch(`{{ url('/products/price-changes/categories') }}/${cat.value}/children`),d=await r.json();d.forEach(x=>opt(sub,x.id,x.text));if(!d.length)document.getElementById('subcategory-empty').classList.remove('d-none')}refreshCounts()});
sub.addEventListener('change',()=>{invalidate('انتخاب محصولات و تنوع‌ها بازنشانی شد.');resetProductPicker(sub.value?'نام، کد، SKU یا مدل کالا را جست‌وجو کنید':'ابتدا زیر‌دسته‌بندی را انتخاب کنید');resetVariantPicker();if(sub.value)enableProductPicker();refreshCounts()});
prod.addEventListener('change',async()=>{invalidate();resetVariantPicker();if(prod.value){setVariantPickerEnabled(true);let url=new URL(`{{ url('/products/price-changes/products') }}/${prod.value}/variants`,location.origin);new FormData(form).forEach((v,k)=>{if(k!=='variant_ids[]')url.searchParams.append(k,v)});let r=await fetch(url),d=await r.json();variantItems=(d||[]).map(v=>({id:String(v.id),name:v.name,sku:v.sku,code:v.sku,model_name:v.model_name||'',sell_price:v.sell_price,is_active:v.is_active}));renderVariantPicker();if(!variantItems.length)msg.textContent='این محصول تنوع قابل انتخاب ندارد.'}refreshCounts()});
['change_type','change_value','rounding_mode'].forEach(id=>document.getElementById(id).addEventListener('change',()=>{invalidate();refreshCounts()}));form.querySelectorAll('input[type=checkbox]').forEach(el=>el.addEventListener('change',()=>{invalidate();if(prod.value)prod.dispatchEvent(new Event('change'));else refreshCounts()}));document.getElementById('change_type').addEventListener('change',()=>{document.getElementById('value-unit').textContent=document.getElementById('change_type').value.includes('percent')?'درصد':'ریال'});
previewBtn.addEventListener('click',async()=>{submitBtn.disabled=true;body.innerHTML='';msg.textContent='در حال محاسبه...';let res=await fetch('{{ route('products.price-changes.preview') }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:scopePayload()});let data=await res.json();if(!res.ok){msg.textContent=Object.values(data.errors||{}).flat().join('، ')||'خطا در پیش‌نمایش';return}(data.items||[]).forEach(i=>body.insertAdjacentHTML('beforeend',`<tr class="preview-row-${i.status}"><td>${escapeHtml(i.product_name)}</td><td>${escapeHtml(i.variant_name)}</td><td>${escapeHtml(i.sku)}</td><td>${money(i.old_price)}</td><td>${money(i.new_price)}</td><td>${money(i.difference)}</td><td>${i.difference_percent??'—'}</td><td>${i.status==='valid'?'<span class="text-success">معتبر</span>':'<span class="text-danger">نیازمند بررسی</span>'}</td><td class="text-danger">${escapeHtml(i.error_message||'—')}</td></tr>`));let s=data.summary||{};document.getElementById('preview-summary').classList.remove('d-none');document.getElementById('preview-summary').innerHTML=`<div class="summary-tile">${s.variants_count} تنوع بررسی شد</div><div class="summary-tile text-success">${s.valid_count} مورد آماده تغییر قیمت</div><div class="summary-tile text-danger">${s.errors_count} مورد نیاز به بررسی دارد</div><div class="summary-tile">جمع قیمت جدید معتبر<br><strong>${money(s.new_total)}</strong></div>`;msg.textContent=s.large_scope_warning?'این سند روی تعداد زیادی تنوع اعمال می‌شود. لطفاً محدوده و پیش‌نمایش را با دقت بررسی کنید.':(s.variants_count?'پیش‌نمایش ساخته شد؛ فقط آیتم‌های معتبر هنگام اعمال تغییر می‌کنند.':'هیچ تنوعی برای تغییر قیمت پیدا نشد.');previewIsValid=!!s.valid_count;submitBtn.disabled=!previewIsValid});
form.addEventListener('submit',e=>{syncVariantSelect();if(!previewIsValid){e.preventDefault();msg.textContent='بدون پیش‌نمایش معتبر امکان ثبت سند وجود ندارد.'}});async function restoreScope(){if(!cat.value){updateText();return}sub.disabled=false;let response=await fetch(`{{ url('/products/price-changes/categories') }}/${cat.value}/children`),children=await response.json();sub.innerHTML='<option value="">همه زیر‌دسته‌ها</option>';children.forEach(x=>opt(sub,x.id,x.text));sub.value=@json((string) old('subcategory_id', ''));if(sub.value){enableProductPicker();@if($selectedProduct)prod.disabled=false;productPickerButton.disabled=false;productPickerButtonText.textContent=@json($selectedProduct->name . ($selectedProduct->code ? ' — '.$selectedProduct->code : ''));prod.dispatchEvent(new Event('change'));@endif}refreshCounts()}restoreScope();
</script>
@endsection
